    paginatedFilter.pagination.records > 0,
  );
  TestValidator.predicate(
    "pagination limit",
    paginatedFilter.pagination.limit <= 100,
  );
  TestValidator.predicate(
    "pagination pages",
    paginatedFilter.pagination.pages >= 1,
