export async function test_api_comment_update_by_author(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup - create and authenticate admin user
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
    },
  });
  // 2. Member setup - create and authenticate member user
  const memberConnection: api.IConnection = { host: connection.host };
  const memberJoinOutput = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      displayName: RandomGenerator.name(),
      passwordConfirmation: RandomGenerator.alphaNumeric(16),
    },
  });
  typia.assert(memberJoinOutput);
  // 3. Use a random section ID as admin sections API is not available
  const sectionId = typia.random<string & tags.Format<"uuid">>();
  // 4. Member creates an article
  const article = await api.functional.discussionBoard.member.articles.create(
    memberConnection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 1 }),
        content: RandomGenerator.content({ paragraphs: 2 }),
        section_id: sectionId,
      },
    },
  );
  typia.assert(article);
  // 5. Member creates a comment on the article
  const initialComment =
    await api.functional.discussionBoard.member.articles.comments.create(
      memberConnection,
      {
        articleId: article.id,
        body: {
          content: RandomGenerator.paragraph({
            sentences: 1,
            wordMin: 5,
            wordMax: 10,
          }),
        },
      },
    );
  typia.assert(initialComment);
  const initialCreatedAt = initialComment.created_at;
  // 6. Admin updates the comment
  const updatedContent = RandomGenerator.paragraph({
    sentences: 2,
    wordMin: 5,
    wordMax: 10,
  });
  const updatedComment =
    await api.functional.discussionBoard.admin.comments.update(
      adminConnection,
      {
        commentId: initialComment.id,
        body: {
          content: updatedContent,
        },
      },
