    commentId: comment.id,
  });
  // 6. Verify comment is deleted by checking it throws 404
  await TestValidator.error("comment not found after deletion", async () => {
    await api.functional.discussionBoard.member.comments.erase(
      adminConnection,
      {
        commentId: comment.id,
      },
    );
  });
}

