  // 8. Test combined expiredFrom and expiredTo filters
  const expiredCombinedFilter =
    await api.functional.discussionBoard.superAdmin.admin_sessions.index(
      authenticatedConnection,
      {
        body: {
          expiredFrom: hourAgo,
          expiredTo: futureTime,
