  // 13. Test sorting by created_at descending
  const sortByCreatedDesc =
    await api.functional.discussionBoard.superAdmin.admin_sessions.index(
      authenticatedConnection,
      {
        body: {
          sortBy: "created_at",
          sortOrder: "desc",
