  // Find the file record
  const file = await MyGlobal.prisma.discussion_board_article_files.findFirst({
    where: {
      id: props.fileId,
      article_id: props.articleId,
    },
  });
  if (!file) {
    throw new HttpException("File not found", 404);
  }
  return {
